import React from "react";
console.log("USER:", post.user);

export default function PostCard({ post, onImageClick }) {

  const isUserObject = typeof post.user === "object";

  return (
    <div className="card">

      <div className="card-header">
        <img 
          src={isUserObject ? post.user?.foto : "https://i.pravatar.cc/50"} 
          alt="" 
        />

        {/* 🔥 SOLO mostrar nombre si existe */}
        {isUserObject && <h4>{post.user?.nombre}</h4>}
      </div>

      <img 
        src={post.imagen} 
        alt="" 
        onClick={() => onImageClick(post)}
        style={{ cursor: "pointer" }}
      />

      <p>{post.descripcion}</p>

      {post.cancion && (
        <audio controls src={post.cancion}></audio>
      )}

    </div>
  );
}
